//! Master a ZX Spectrum distribution tape (`build198x tape --machine
//! sinclair-zx-spectrum`): an auto-running BASIC loader, a
//! SCREEN$ loading screen and the program's CODE, in the order the loader
//! reads them. Byte layouts belong to Format198x; this module composes the
//! blocks and checks that the program fits where the loader puts it.
//!
//! The loader is generated by default, which lets every address be checked.
//! An authored loader replaces it; the tool never rewrites one, so its
//! `CLEAR` and `USR` are its author's to get right.

use crate::basic::{self, Error, Machine, lint};
use format198x_sinclair_zx_spectrum_scr as scr;
use format198x_sinclair_zx_spectrum_tap::{Header, HeaderKind, TapBlock, encode};

/// Where a BASIC program starts on a 16K or 48K Spectrum with no Interface 1:
/// the ROM's initial value of the system variable PROG.
pub const PROG: u32 = 23755;

/// Where `LOAD ""SCREEN$` puts its block: the start of the display file.
pub const SCREEN_START: u16 = 16384;

/// The screen channel's output-address low byte (channel data begins at
/// 23734 on a machine with no Interface 1; `K` takes five bytes, then `S`).
const S_CHANNEL_OUTPUT: u16 = 23739;

/// Low byte of `$096F`, the `RET` that ends the routine before SA-CONTRL
/// (Logan and O'Hara, *The Complete Spectrum ROM Disassembly*). Pointing the
/// screen channel at it discards ROM printing, so "Bytes: name" does not
/// appear over the loading screen while the CODE block loads.
const SILENT_OUTPUT: u8 = 0x6f;

/// Low byte of `$09F4`, PRINT-OUT: the screen channel's own output routine,
/// restored before the program runs so ROM printing works for it.
const PRINT_OUT: u8 = 0xf4;

/// Bytes the generated loader needs between the end of its own program and
/// the CODE. `CLEAR` puts the machine stack just below the CODE; each `LOAD`
/// then reserves header space in the workspace and calls TEST-ROOM, which
/// demands 80 spare bytes between the workspace and the stack. Measured on
/// the 48K ROM in Emu198x with the 130-byte loader: CODE at 24040 loads and
/// runs, and at 24039 the ROM stops with "4 Out of memory, 40:1".
const LOADER_HEADROOM: u32 = 155;

/// The machine the tape is for, which sets the top of RAM.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Model {
    /// 16K Spectrum: RAM ends at 32767.
    K16,
    /// 48K Spectrum (and later machines in 48K mode): RAM ends at 65535.
    K48,
}

impl Model {
    /// The id the CLI takes: `16k` or `48k`.
    #[must_use]
    pub fn from_id(id: &str) -> Option<Self> {
        match id {
            "16k" => Some(Self::K16),
            "48k" => Some(Self::K48),
            _ => None,
        }
    }

    /// The id the CLI takes.
    #[must_use]
    pub fn id(self) -> &'static str {
        match self {
            Self::K16 => "16k",
            Self::K48 => "48k",
        }
    }

    /// One past the last byte of RAM.
    #[must_use]
    pub fn ram_end(self) -> u32 {
        match self {
            Self::K16 => 32768,
            Self::K48 => 65536,
        }
    }
}

/// Which BASIC loader leads the tape.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Loader<'a> {
    /// The standard loader, written by this module.
    Generated {
        /// `BORDER` colour, 0–7.
        border: u8,
        /// `PAPER` colour, 0–7.
        paper: u8,
        /// `INK` colour, 0–7.
        ink: u8,
        /// The address `RANDOMIZE USR` calls; `None` for the load address.
        entry: Option<u16>,
    },
    /// An authored listing, used as written.
    Authored(&'a str),
}

/// What to put on the tape.
#[derive(Debug, Clone, Copy)]
pub struct Options<'a> {
    /// The assembled program.
    pub code: &'a [u8],
    /// Where the CODE block loads.
    pub load_address: u16,
    /// A 6912-byte SCREEN$, or `None` for the built-in test card.
    pub screen: Option<&'a [u8]>,
    /// The BASIC loader.
    pub loader: Loader<'a>,
    /// The machine, which sets the top of RAM.
    pub model: Model,
    /// The loader block's tape name.
    pub name: &'a str,
    /// The CODE block's tape name.
    pub code_name: &'a str,
    /// The screen block's tape name.
    pub screen_name: &'a str,
}

/// A mastered tape and what went onto it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Built {
    /// The `.tap` bytes: loader, screen and CODE, each a header and data pair.
    pub bytes: Vec<u8>,
    /// The BASIC listing that leads the tape.
    pub loader_source: String,
    /// The tokenised loader's length.
    pub loader_length: usize,
    /// The line the loader runs from.
    pub autorun: u16,
    /// The `CLEAR` address of a generated loader.
    pub clear: Option<u16>,
    /// The address a generated loader calls.
    pub entry: Option<u16>,
    /// Whether the screen is the built-in test card.
    pub test_card: bool,
}

/// Compose the tape.
///
/// # Errors
/// Refuses a screen that is not 6912 bytes, empty CODE, CODE that runs past
/// the model's RAM, an entry outside the CODE, a load address too low for the
/// loader to `CLEAR` beneath it (or, for an authored loader, inside the
/// loader itself), and a loader that fails lint or tokenising.
pub fn build(options: &Options<'_>) -> Result<Built, Error> {
    let fail = |message: String| Error { line: 0, message };

    let card;
    let (screen, test_card) = match options.screen {
        Some(bytes) => (bytes, false),
        None => {
            card = test_card();
            (card.as_slice(), true)
        }
    };
    if screen.len() != scr::FILE_LEN {
        return Err(fail(format!(
            "a SCREEN$ is {} bytes; this one is {}",
            scr::FILE_LEN,
            screen.len()
        )));
    }

    let load = u32::from(options.load_address);
    let length = options.code.len();
    if length == 0 {
        return Err(fail("the CODE is empty".to_owned()));
    }
    let end = load.saturating_add(u32::try_from(length).unwrap_or(u32::MAX));
    if end > options.model.ram_end() {
        return Err(fail(format!(
            "{length} bytes of CODE at {load} end at {}, past the {} Spectrum's last RAM address {}",
            end - 1,
            options.model.id().to_uppercase(),
            options.model.ram_end() - 1
        )));
    }
    let code_length = u16::try_from(length).map_err(|_| {
        fail(format!(
            "{length} bytes of CODE is more than a tape block holds"
        ))
    })?;

    let (loader_source, clear, entry) = match options.loader {
        Loader::Generated {
            border,
            paper,
            ink,
            entry,
        } => {
            for (what, value) in [("border", border), ("paper", paper), ("ink", ink)] {
                if value > 7 {
                    return Err(fail(format!("{what} colour {value} is not 0–7")));
                }
            }
            let entry = entry.unwrap_or(options.load_address);
            if u32::from(entry) < load || u32::from(entry) >= end {
                return Err(fail(format!(
                    "entry {entry} is outside the CODE, which occupies {load}–{}",
                    end - 1
                )));
            }
            let clear = options.load_address.checked_sub(1).ok_or_else(|| {
                fail("the CODE cannot load at address 0, which is ROM".to_owned())
            })?;
            (
                generated_loader(border, paper, ink, clear, entry),
                Some(clear),
                Some(entry),
            )
        }
        Loader::Authored(source) => (source.to_owned(), None, None),
    };

    let findings = lint::check(Machine::SinclairZxSpectrum, &loader_source)?;
    if let Some(first) = findings.first() {
        return Err(Error {
            line: first.line,
            message: format!("{}: {}", first.rule, first.message),
        });
    }
    let loader = basic::build(
        Machine::SinclairZxSpectrum,
        &loader_source,
        options.name,
        true,
    )?;
    let autorun = loader
        .autorun
        .ok_or_else(|| fail("the BASIC loader does not run itself".to_owned()))?;

    let floor = match options.loader {
        Loader::Generated { .. } => minimum_load_address(loader.program_length),
        Loader::Authored(_) => {
            PROG.saturating_add(u32::try_from(loader.program_length).unwrap_or(u32::MAX))
        }
    };
    if load < floor {
        let why = match options.loader {
            Loader::Generated { .. } => "the loader needs memory below it to CLEAR and LOAD",
            Loader::Authored(_) => "it would overwrite the BASIC loader",
        };
        return Err(fail(format!(
            "CODE at {load} is too low: {why}; load it at {floor} or above"
        )));
    }

    let mut bytes = loader.bytes;
    bytes.extend(encode(&[
        Header::new(
            HeaderKind::Code,
            &basic::tape_name(options.screen_name),
            6912,
            SCREEN_START,
            32768,
        )
        .block(),
        TapBlock::data(screen.to_vec()),
        Header::new(
            HeaderKind::Code,
            &basic::tape_name(options.code_name),
            code_length,
            options.load_address,
            32768,
        )
        .block(),
        TapBlock::data(options.code.to_vec()),
    ]));

    Ok(Built {
        bytes,
        loader_source,
        loader_length: loader.program_length,
        autorun,
        clear,
        entry,
        test_card,
    })
}

/// The lowest address a generated loader can `CLEAR` beneath and still load
/// its blocks, given the tokenised loader's length.
#[must_use]
pub fn minimum_load_address(loader_length: usize) -> u32 {
    PROG.saturating_add(u32::try_from(loader_length).unwrap_or(u32::MAX))
        .saturating_add(LOADER_HEADROOM)
}

/// The standard loader, in the listed form: colours and `CLEAR` first, then
/// the screen, then the CODE with ROM printing silenced so its header message
/// does not land on the screen, then printing restored and the program called.
#[must_use]
pub fn generated_loader(border: u8, paper: u8, ink: u8, clear: u16, entry: u16) -> String {
    format!(
        "  10 BORDER {border}: PAPER {paper}: INK {ink}: CLEAR {clear}\n  \
         20 LOAD \"\"SCREEN$ \n  \
         30 POKE {S_CHANNEL_OUTPUT},{SILENT_OUTPUT}\n  \
         40 LOAD \"\"CODE \n  \
         50 POKE {S_CHANNEL_OUTPUT},{PRINT_OUT}: RANDOMIZE USR {entry}\n"
    )
}

/// A built-in SCREEN$ for tapes whose art does not exist yet: eight colour
/// bars, dim above and bright below, with a one-pixel frame and centre cross
/// drawn in each bar's contrasting ink.
#[must_use]
pub fn test_card() -> Vec<u8> {
    let mut screen = scr::Screen::blank();
    for y in 0..scr::HEIGHT {
        for x in 0..scr::WIDTH {
            let edge = x == 0 || y == 0 || x == scr::WIDTH - 1 || y == scr::HEIGHT - 1;
            let cross = x == scr::WIDTH / 2 || y == scr::HEIGHT / 2;
            if edge || cross {
                screen.bitmap[y * scr::COLUMNS + x / 8] |= 0x80 >> (x & 7);
            }
        }
    }
    for row in 0..scr::ATTRIBUTE_ROWS {
        for column in 0..scr::COLUMNS {
            // White, yellow, cyan, green, magenta, red, blue, black: the
            // Spectrum's colours in falling brightness, four columns each.
            let paper = 7 - u8::try_from(column / 4).unwrap_or(7);
            let ink = if paper >= 4 { 0 } else { 7 };
            let bright = if row >= scr::ATTRIBUTE_ROWS / 2 {
                0x40
            } else {
                0
            };
            screen.attributes[row * scr::COLUMNS + column] = bright | (paper << 3) | ink;
        }
    }
    // A blank screen's buffers are the lengths `encode` requires.
    scr::encode(&screen).unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;
    use format198x_sinclair_zx_spectrum_tap::decode;

    #[test]
    fn an_impossible_loader_cannot_have_a_loadable_address() {
        assert!(minimum_load_address(usize::MAX) > u32::from(u16::MAX));
    }

    fn options(code: &[u8]) -> Options<'_> {
        Options {
            code,
            load_address: 32768,
            screen: None,
            loader: Loader::Generated {
                border: 0,
                paper: 0,
                ink: 0,
                entry: None,
            },
            model: Model::K48,
            name: "game",
            code_name: "game",
            screen_name: "screen",
        }
    }

    #[test]
    fn a_tape_is_loader_screen_and_code_in_that_order() {
        let built = build(&options(&[0xc9])).unwrap();
        let blocks = decode(&built.bytes).unwrap();
        assert_eq!(blocks.len(), 6);
        let headers: Vec<Header> = [0, 2, 4]
            .iter()
            .map(|&i| Header::from_payload(&blocks[i].data).unwrap())
            .collect();
        assert_eq!(headers[0].kind, HeaderKind::Program);
        assert_eq!(headers[0].param1, built.autorun);
        assert_eq!(usize::from(headers[0].length), built.loader_length);
        assert_eq!(
            (
                headers[1].kind,
                headers[1].name.as_str(),
                headers[1].length,
                headers[1].param1
            ),
            (HeaderKind::Code, "screen", 6912, 16384)
        );
        assert_eq!(
            (
                headers[2].kind,
                headers[2].name.as_str(),
                headers[2].length,
                headers[2].param1
            ),
            (HeaderKind::Code, "game", 1, 32768)
        );
        assert_eq!(blocks[3].data, test_card());
        assert_eq!(blocks[5].data, [0xc9]);
        assert!(built.test_card);
    }

    #[test]
    fn the_generated_loader_is_lint_clean_and_calls_the_entry() {
        let mut o = options(&[0, 0, 0xc9]);
        o.loader = Loader::Generated {
            border: 1,
            paper: 2,
            ink: 7,
            entry: Some(32770),
        };
        let built = build(&o).unwrap();
        assert_eq!(built.clear, Some(32767));
        assert_eq!(built.entry, Some(32770));
        assert_eq!(
            lint::check(Machine::SinclairZxSpectrum, &built.loader_source).unwrap(),
            []
        );
        assert!(
            built
                .loader_source
                .contains("BORDER 1: PAPER 2: INK 7: CLEAR 32767")
        );
        assert!(built.loader_source.ends_with("RANDOMIZE USR 32770\n"));
    }

    #[test]
    fn an_authored_loader_is_used_as_written() {
        let source = "  10 CLEAR 32767\n  20 LOAD \"\"SCREEN$ \n  30 LOAD \"\"CODE \n  40 RANDOMIZE USR 32768\n";
        let mut o = options(&[0xc9]);
        o.loader = Loader::Authored(source);
        let built = build(&o).unwrap();
        assert_eq!(built.loader_source, source);
        assert_eq!((built.clear, built.entry), (None, None));
        let alone = basic::build(Machine::SinclairZxSpectrum, source, "game", true).unwrap();
        assert!(built.bytes.starts_with(&alone.bytes));
    }

    #[test]
    fn building_twice_gives_identical_bytes() {
        let code: Vec<u8> = (0..=255).collect();
        assert_eq!(build(&options(&code)), build(&options(&code)));
    }

    #[test]
    fn code_must_fit_the_model() {
        let code = vec![0; 32768];
        assert!(
            build(&options(&code)).is_ok(),
            "32768..65535 fills a 48K exactly"
        );
        assert!(build(&options(&vec![0; 32769])).is_err());

        let small = vec![0; 1];
        let mut o = options(&small);
        o.model = Model::K16;
        assert!(build(&o).unwrap_err().message.contains("16K"));
        o.load_address = 32767;
        assert!(build(&o).is_ok(), "the last byte of a 16K's RAM is 32767");
    }

    #[test]
    fn the_entry_must_be_inside_the_code() {
        for entry in [32767, 32770] {
            let mut o = options(&[0, 0]);
            o.loader = Loader::Generated {
                border: 0,
                paper: 0,
                ink: 0,
                entry: Some(entry),
            };
            assert!(build(&o).unwrap_err().message.contains("outside the CODE"));
        }
    }

    #[test]
    fn refuses_bad_screens_empty_code_and_colours() {
        let short = [0u8; 6911];
        let mut o = options(&[0xc9]);
        o.screen = Some(&short);
        assert!(build(&o).unwrap_err().message.contains("6912"));
        assert!(build(&options(&[])).unwrap_err().message.contains("empty"));
        let mut o = options(&[0xc9]);
        o.loader = Loader::Generated {
            border: 8,
            paper: 0,
            ink: 0,
            entry: None,
        };
        assert!(build(&o).unwrap_err().message.contains("border"));
    }

    #[test]
    fn code_cannot_sit_on_the_loader() {
        let mut o = options(&[0xc9]);
        o.load_address = 23800;
        assert!(build(&o).unwrap_err().message.contains("too low"));

        o.loader = Loader::Authored("  10 RANDOMIZE USR 23760\n");
        o.load_address = 23760;
        assert!(
            build(&o)
                .unwrap_err()
                .message
                .contains("overwrite the BASIC loader")
        );
    }

    #[test]
    fn the_generated_loader_needs_the_measured_headroom() {
        // Emu198x's 48K ROM run: 24040 loads and runs; 24039 stops with
        // "4 Out of memory, 40:1" (see LOADER_HEADROOM).
        let mut o = options(&[0xc9]);
        o.load_address = 24040;
        let built = build(&o).unwrap();
        assert_eq!(built.loader_length, 130);
        assert_eq!(minimum_load_address(built.loader_length), 24040);
        o.load_address = 24039;
        assert!(
            build(&o)
                .unwrap_err()
                .message
                .contains("load it at 24040 or above")
        );
    }

    #[test]
    fn the_test_card_is_a_stable_screen() {
        let card = test_card();
        assert_eq!(card.len(), 6912);
        let screen = scr::decode(&card).unwrap();
        assert_eq!(screen.pixel(0, 0), Some(true));
        assert_eq!(screen.pixel(1, 1), Some(false));
        assert_eq!(screen.attributes[0], 0o070, "white paper, black ink, dim");
        assert_eq!(
            screen.attributes[767], 0o107,
            "black paper, white ink, bright"
        );
    }
}
